/*
 * <chrome-text> — headings set in Blender-rendered chrome, one image per word
 * ---------------------------------------------------------------------------
 *   <h2><chrome-text>Ready for your next set?</chrome-text></h2>
 *
 * Every word was rendered in Blender (Werkzeuge/chrome-assets/, see readme
 * there) and exported to _ds/chrome/schrift/. The list of rendered words is
 * _ds/chrome/schrift/woerter.js (window.NA_SCHRIFT, generated by
 * exportieren.py) — load it and this file from the real <head>, not from
 * <helmet>, so both exist before the first render.
 *
 * One image per word, not per heading, so a heading still wraps like text at
 * any width. All word images share one canvas height and baseline, so the
 * font-size of the heading alone sets their size.
 *
 * Fallback is the CSS chrome text: as long as any word of a heading has no
 * render (new copy, typo fix, export not run yet) or an image fails to load,
 * the element shows its own text and nothing looks broken. The real text is
 * also kept, visually hidden, for screen readers, search and translation.
 *
 * While the images are showing, the element carries data-ready; styles.css
 * then switches the heading's CSS chrome (gradient + SVG filter) off, so the
 * filter doesn't re-light the rendered metal.
 *
 * Why a custom element with a shadow root: the dc runtime re-renders pages
 * with React and resets attributes it doesn't know. The images live in the
 * shadow root, where a re-render can't touch them, and an observer puts
 * data-ready straight back (same approach as turntable.js).
 */
(function () {
  if (!window.customElements || customElements.get('chrome-text')) return;

  const isVertical = (el) => /^(vertical|sideways)/.test(getComputedStyle(el).writingMode);

  class ChromeText extends HTMLElement {
    connectedCallback() {
      if (!this._root) {
        this._root = this.attachShadow({ mode: 'open' });
        this._root.innerHTML = '<slot></slot>';
        // Copy changes from a re-render → set the new words.
        new MutationObserver(() => this._render())
          .observe(this, { childList: true, characterData: true, subtree: true });
        // The runtime strips unknown attributes on re-render; put ours back.
        new MutationObserver(() => {
          if (this._ready && !this.hasAttribute('data-ready')) this.setAttribute('data-ready', '');
        }).observe(this, { attributes: true, attributeFilter: ['data-ready'] });
        // .vertical titles turn horizontal on phones: swap image variants.
        window.addEventListener('resize', () => {
          if (this._vertical !== undefined && isVertical(this) !== this._vertical) this._render(true);
        }, { passive: true });
      }
      this._render();
    }

    _fallback() {
      this._ready = false;
      this._key = null;
      this.removeAttribute('data-ready');
      this._root.innerHTML = '<slot></slot>';
    }

    async _render(force) {
      const m = window.NA_SCHRIFT;
      const text = this.textContent.replace(/\s+/g, ' ').trim();
      const words = text ? text.split(' ') : [];
      if (!m || !words.length || words.some((w) => !m.woerter[w])) return this._fallback();

      const vertical = isVertical(this);
      if (vertical && words.some((w) => !m.woerter[w].v)) return this._fallback();
      const key = text + (vertical ? '|v' : '');
      if (!force && key === this._key) return;
      this._key = key;
      this._vertical = vertical;

      const [lo, hi] = m.groessen;              // px per em of the two exports
      const file = (d, em, ext) => `${m.pfad}${d}${vertical ? '-v' : ''}-${em}.${ext}`;
      const frag = document.createDocumentFragment();
      const style = document.createElement('style');
      // Sizes in em of the host's font-size; see woerter.js for the numbers.
      style.textContent = `
        :host { display: inline; }
        .sr { position: absolute; width: 1px; height: 1px; margin: -1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
        img { display: inline; ${vertical ? 'width' : 'height'}: ${m.hoehe}em; ${vertical ? 'height' : 'width'}: auto;
              vertical-align: ${-m.grundlinie}em; margin-block: ${-m.ueberstand_oben}em ${-m.ueberstand_unten}em;
              margin-inline: ${-(m.rand || 0)}em; }`;   /* side room for the italic, not extra word space */
      frag.append(style);
      const sr = document.createElement('span');
      sr.className = 'sr';
      sr.textContent = text;
      frag.append(sr);

      const imgs = words.map((w, i) => {
        const d = m.woerter[w].d;
        const pic = document.createElement('picture');
        pic.setAttribute('aria-hidden', 'true');
        const src = document.createElement('source');
        src.type = 'image/avif';
        src.srcset = `${file(d, lo, 'avif')} 1x, ${file(d, hi, 'avif')} 2x`;
        const img = document.createElement('img');
        img.alt = '';
        img.decoding = 'async';
        // The page title is the first thing seen; don't queue it behind the
        // turntable's 120 frames.
        if (this.closest('h1')) img.fetchPriority = 'high';
        img.src = file(d, lo, 'webp');
        img.srcset = `${img.src} 1x, ${file(d, hi, 'webp')} 2x`;
        pic.append(src, img);
        if (i) frag.append(' ');
        frag.append(pic);
        return img;
      });

      // Swap only once every word has loaded, so the heading never shows half
      // rendered / half CSS, or an empty gap while the images arrive.
      const staging = document.createElement('div');
      staging.append(frag);
      // load events, not img.decode(): decode() stalls while a page isn't
      // drawn (background tab), and the swap would wait for no reason.
      const geladen = (img) => new Promise((ok, fehler) => {
        if (img.complete && img.naturalWidth) return ok();
        img.addEventListener('load', ok, { once: true });
        img.addEventListener('error', fehler, { once: true });
      });
      try {
        await Promise.all(imgs.map(geladen));
      } catch (e) {
        if (this._key === key) this._fallback();
        return;
      }
      if (this._key !== key) return;            // the text changed meanwhile
      this._root.replaceChildren(...staging.childNodes);
      this._ready = true;
      this.setAttribute('data-ready', '');
    }
  }

  customElements.define('chrome-text', ChromeText);
})();
